//   support-ticketing-app/backend/SupportDesk.Api/Auth/ApiExceptionHandler.cs with the review's F4 fix applied
//   (astraupskill/06-SOLUTIONS-AND-REVIEW.md:31): generic detail for the 500 arm, real message logged.
// The ASP.NET pieces (HttpContext, ILogger, IProblemDetailsService, ProblemDetails) are replaced by small
// recording stand-ins so the handler compiles and runs on its own; TryHandleAsync's body is the same code
// as the adapted handler next to it.
namespace SupportDesk.Kata;

public sealed class NotFoundException(string message) : Exception(message);

public sealed class ForbiddenException(string message) : Exception(message);

public sealed class ConcurrencyException(string message) : Exception(message);

public sealed class DomainException(string message) : Exception(message);

public sealed class BadHttpRequestException(string message) : Exception(message);

public static class StatusCodes
{
    public const int Status400BadRequest = 400;
    public const int Status403Forbidden = 403;
    public const int Status404NotFound = 404;
    public const int Status409Conflict = 409;
    public const int Status500InternalServerError = 500;
}

public sealed class HttpRequest
{
    public string Path { get; set; } = "/";
}

public sealed class HttpResponse
{
    public int StatusCode { get; set; } = 200;
}

public sealed class HttpContext
{
    public string TraceIdentifier { get; init; } = "0HN-TRACE";
    public HttpRequest Request { get; } = new();
    public HttpResponse Response { get; } = new();
}

public sealed class ProblemDetails
{
    public int? Status { get; set; }
    public string? Title { get; set; }
    public string? Detail { get; set; }
}

public sealed class ProblemDetailsContext
{
    public required HttpContext HttpContext { get; init; }
    public Exception? Exception { get; init; }
    public required ProblemDetails ProblemDetails { get; init; }
}

public interface IProblemDetailsService
{
    ValueTask<bool> TryWriteAsync(ProblemDetailsContext context);
}

/// <summary>Records every problem written to the client.</summary>
public sealed class RecordingProblemDetailsService : IProblemDetailsService
{
    public List<ProblemDetails> Written { get; } = [];

    public ValueTask<bool> TryWriteAsync(ProblemDetailsContext context)
    {
        Written.Add(context.ProblemDetails);
        return ValueTask.FromResult(true);
    }
}

public interface ILogger<T>
{
    void LogError(Exception exception, string message, params object?[] args);
}

/// <summary>Records every error logged server-side.</summary>
public sealed class RecordingLogger<T> : ILogger<T>
{
    public List<(Exception Exception, string Message)> Errors { get; } = [];

    public void LogError(Exception exception, string message, params object?[] args) => Errors.Add((exception, message));
}

public sealed class ApiExceptionHandler
{
    private readonly IProblemDetailsService _problemDetails;
    private readonly ILogger<ApiExceptionHandler> _logger;

    public ApiExceptionHandler(IProblemDetailsService problemDetails, ILogger<ApiExceptionHandler> logger)
    {
        _problemDetails = problemDetails;
        _logger = logger;
    }

    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        var (statusCode, title) = exception switch
        {
            NotFoundException => (StatusCodes.Status404NotFound, "Not found"),
            ForbiddenException => (StatusCodes.Status403Forbidden, "Forbidden"),
            ConcurrencyException => (StatusCodes.Status409Conflict, "Concurrency conflict"),
            DomainException => (StatusCodes.Status400BadRequest, "Invalid request"),
            BadHttpRequestException => (StatusCodes.Status400BadRequest, "Invalid request"),
            _ => (StatusCodes.Status500InternalServerError, "Unexpected error")
        };

        // Known exceptions carry messages written for the client (e.g. the 409 version hint).
        // Anything else is logged with its real message and answered generically.
        var detail = statusCode == StatusCodes.Status500InternalServerError
            ? "An unexpected error occurred. Reference: " + httpContext.TraceIdentifier
            : exception.Message;
        if (statusCode == StatusCodes.Status500InternalServerError)
        {
            _logger.LogError(exception, "Unhandled exception for {Path}", httpContext.Request.Path);
        }

        httpContext.Response.StatusCode = statusCode;

        return await _problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = statusCode,
                Title = title,
                Detail = detail
            }
        });
    }
