using SupportDesk.Kata;

// netzen has no handler tests upstream (SupportDesk.Api.Tests/TicketSafetyTests.cs covers tickets only):
// these pin the behavior review F4 (astraupskill/06-SOLUTIONS-AND-REVIEW.md:31) asks for.
public sealed class ApiExceptionHandlerTests
{
    private static async Task<(HttpContext Ctx, ProblemDetails Problem, RecordingLogger<ApiExceptionHandler> Log)> Handle(Exception exception)
    {
        var problems = new RecordingProblemDetailsService();
        var log = new RecordingLogger<ApiExceptionHandler>();
        var ctx = new HttpContext { TraceIdentifier = "0HN7-REF-42", Request = { Path = "/api/tickets/7" } };
        Assert.True(await new ApiExceptionHandler(problems, log).TryHandleAsync(ctx, exception, CancellationToken.None));
        return (ctx, Assert.Single(problems.Written), log);
    }

    [Fact(DisplayName = "an unexpected exception's message never reaches the client: a generic 500 detail with the trace reference (review F4, astraupskill/06-SOLUTIONS-AND-REVIEW.md:31)")]
    public async Task UnexpectedException_DetailIsGeneric()
    {
        var (ctx, problem, _) = await Handle(new InvalidOperationException("Login failed for user 'sa'. Server=sql-prod-01;Password=hunter2"));

        Assert.Equal(500, ctx.Response.StatusCode);
        Assert.Equal("Unexpected error", problem.Title);
        Assert.DoesNotContain("hunter2", problem.Detail);
        Assert.Contains("0HN7-REF-42", problem.Detail);
    }

    [Fact(DisplayName = "an unexpected exception is logged server-side with the real exception (review F4)")]
    public async Task UnexpectedException_IsLogged()
    {
        var boom = new NullReferenceException("ticket.Assignee was null");

        var (_, _, log) = await Handle(boom);

        Assert.Same(boom, Assert.Single(log.Errors).Exception);
    }

    [Fact(DisplayName = "a known exception keeps its client-facing message: the 409 version hint")]
    public async Task ConcurrencyException_KeepsMessage()
    {
        var (ctx, problem, log) = await Handle(new ConcurrencyException("Ticket was changed by someone else (version 4)."));

        Assert.Equal(409, ctx.Response.StatusCode);
        Assert.Equal("Ticket was changed by someone else (version 4).", problem.Detail);
        Assert.Empty(log.Errors);
    }

    [Fact(DisplayName = "NotFoundException answers 404 'Not found'")]
    public async Task NotFound_Is404()
    {
        var (ctx, problem, _) = await Handle(new NotFoundException("Ticket 7 was not found."));

        Assert.Equal(404, ctx.Response.StatusCode);
        Assert.Equal("Not found", problem.Title);
    }
}
